 * Bulk invite. The seat quota is checked once for the whole batch — inviting
 * five people into a plan with three free seats must fail as a batch rather
 * than half-succeeding — and the rate limit is charged per invite.
 */
export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  return issueInvitations(actor, input, []);
}

/**
 * `replacing` names invitations that are being re-issued: they neither hold a
 * seat nor block their own address, and are revoked only once the whole batch
 * has been accepted.
 */
async function issueInvitations(
  actor: Actor,
  input: InviteMembersInput,
  replacing: readonly InvitationId[],
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  const verdict = await consumeRateLimit(
    input.orgId,
    INVITE_BUCKET,
    input.invites.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const invites = input.invites.map((invite) => ({
    ...invite,
    email: normalizeEmail(invite.email),
  }));

  const pending = (await invitationRepo.listPendingInvitations(input.orgId))
    .filter((row) => !replacing.includes(row.id));
  const pendingEmails = new Set(pending.map((row) => normalizeEmail(row.email)));

  const seen = new Set<string>();
  for (const invite of invites) {
    if (seen.has(invite.email)) {
      throw new Error(`${invite.email} is named more than once`);
    }
    seen.add(invite.email);

    if (await memberRepo.findLiveMemberByEmail(input.orgId, invite.email)) {
      throw new Error(`${invite.email} is already a member of this workspace`);
    }
    if (pendingEmails.has(invite.email)) {
      throw new Error(`${invite.email} already has a pending invitation`);
    }
  }

  const seatsUsed =
    (await memberRepo.countActiveMembers(input.orgId)) + pending.length;

  if (wouldExceedLimit(org.plan, "seats", seatsUsed, invites.length)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  for (const id of replacing) {
    await invitationRepo.revokeInvitation(input.orgId, id);
  }

  const invitations: Invitation[] = [];

  for (const invite of invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      input.orgId,
      {
        orgId: input.orgId,
        email: invite.email,
        role: invite.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId: input.orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invite.email,
      role: invite.role,
    });
  }

  return invitations;
}

function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

